from pathlib import Path
import json, subprocess
root=Path.cwd()
work=root.parent/'clone-work'/'migration-audit'
work.mkdir(parents=True,exist_ok=True)
test='''package grpc_test

import (
 "bytes"
 "testing"
 oldproto "github.com/golang/protobuf/proto"
 "google.golang.org/grpc/codes"
 "google.golang.org/grpc/encoding"
 _ "google.golang.org/grpc/encoding/proto"
 "google.golang.org/grpc/internal/binarylog"
 legacy "google.golang.org/grpc/reflection/grpc_testing_not_regenerate"
 "google.golang.org/grpc/status"
)

func TestReviewMigrationLegacy(t *testing.T) {
 msg := &legacy.SearchResponseV3{State: legacy.SearchResponseV3_FRESH}
 wire, err := oldproto.Marshal(msg)
 if err != nil { t.Fatal(err) }
 t.Run("CodecMarshal", func(t *testing.T) {
  got, err := encoding.GetCodec("proto").Marshal(msg)
  if err != nil || !bytes.Equal(got, wire) { t.Fatalf("Marshal = %x, %v; want %x, nil", got, err, wire) }
 })
 t.Run("CodecUnmarshal", func(t *testing.T) {
  got := new(legacy.SearchResponseV3)
  err := encoding.GetCodec("proto").Unmarshal(wire, got)
  if err != nil || !oldproto.Equal(msg, got) { t.Fatalf("Unmarshal = %v, %v; want %v, nil", got, err, msg) }
 })
 t.Run("StatusDetails", func(t *testing.T) {
  st, err := status.New(codes.Internal, "test").WithDetails(msg)
  if err != nil { t.Fatal(err) }
  got := st.Details()[0]
  detail, ok := got.(*legacy.SearchResponseV3)
  if !ok { t.Fatalf("Details returned %T; want *grpc_testing_not_regenerate.SearchResponseV3", got) }
  if !oldproto.Equal(detail, msg) { t.Fatalf("Details = %v; want %v", detail, msg) }
 })
 t.Run("BinaryLogServerMessage", func(t *testing.T) {
  logger := binarylog.NewTruncatingMethodLogger(^uint64(0), ^uint64(0))
  got := logger.Build(&binarylog.ServerMessage{Message: msg}).GetMessage()
  if got.Length != uint32(len(wire)) || !bytes.Equal(got.Data, wire) { t.Fatalf("ServerMessage = length %d, data %x; want %d, %x", got.Length, got.Data, len(wire), wire) }
 })
}
'''
path=work/'migration_test.go'
path.write_text(test)
replace={str(root/'review_migration_test.go'):str(path)}
(work/'head-overlay.json').write_text(json.dumps({'Replace':replace}))
for source in ['encoding/proto/proto.go','internal/status/status.go','internal/binarylog/method_logger.go']:
 dest=work/('base-'+source.replace('/','-'))
 dest.write_bytes(subprocess.check_output(['git','show','main:'+source]))
 replace[str(root/source)]=str(dest)
(work/'base-overlay.json').write_text(json.dumps({'Replace':replace}))
PY

